// src/services/staticData.ts
// Read-only data source for the static (GitHub Pages) build.
// Mirrors the filtering/sorting/pagination of the API server over JSON files
// exported to `${PUBLIC_URL}/data` (see RNA-Undesign/server/export_static.py).

export const IS_STATIC = process.env.REACT_APP_STATIC === 'true';

const DATA_URL = `${process.env.PUBLIC_URL || ''}/data`;

type Json = Record<string, any>;

const jsonCache: Record<string, Promise<Json[]>> = {};
const svgCache: Record<string, Promise<string>> = {};

function loadJson(name: string): Promise<Json[]> {
  if (!jsonCache[name]) {
    jsonCache[name] = fetch(`${DATA_URL}/${name}`).then(res => {
      if (!res.ok) throw new Error(`Error: ${res.status} - ${res.statusText}`);
      return res.json();
    });
  }
  return jsonCache[name];
}

export function loadSvg(key: string): Promise<string> {
  if (!svgCache[key]) {
    svgCache[key] = fetch(`${DATA_URL}/svg/${key}.svg`).then(res => (res.ok ? res.text() : ''));
  }
  return svgCache[key];
}

const naturalKey = (s: string) =>
  s.split(/(\d+)/).map(t => (/^\d+$/.test(t) ? t.padStart(12, '0') : t.toLowerCase())).join('');

const MOTIF_SORT: Record<string, (m: Json) => number | string> = {
  ID: m => m.id_uniq,
  'Number of Occurrences': m => m.occurrences.length,
  'Number of Families': m => Object.keys(m.family2count).length,
  Length: m => m.length,
  'Boundary Pairs': m => m.bpairs.length,
  'Internal Pairs': m => m.ipairs.length,
  'Number of Loops': m => m.cardinality,
};

const STRUC_SORT: Record<string, (s: Json) => number | string> = {
  ID: s => naturalKey(s._id),
  Length: s => s.length,
  'Number of Motifs': s => s.motifs_id.length,
  'Number of Loops': s => s.num_loops,
};

function sortItems(items: Json[], table: Record<string, (x: Json) => number | string>, field: string, order: string) {
  // stable in both directions (ties keep data order), like Python's sorted(reverse=...)
  const key = table[field] || table.ID;
  const dir = order === 'desc' ? -1 : 1;
  return [...items].sort((a, b) => {
    const ka = key(a);
    const kb = key(b);
    return ka < kb ? -dir : ka > kb ? dir : 0;
  });
}

const paginate = (items: Json[], page: number, limit: number) =>
  items.slice((Math.max(page, 1) - 1) * limit, Math.max(page, 1) * limit);

const famSet = (families: string[]) => new Set(families.map(f => f.toLowerCase()).filter(Boolean));

async function withMotifSvg(m: Json): Promise<Json> {
  return { ...m, motif_svg: await loadSvg(`motif_${m._id}`) };
}

async function withStrucSvgs(s: Json, motifNums: string[]): Promise<Json> {
  const keys = motifNums
    .map(n => n.replace('ymotif', '').trim())
    .filter(n => s.occurrence_keys.includes(n));
  const svgKeys = keys.length ? keys.map(k => `struc_${s._id}_${k}`) : [`struc_${s._id}_all`];
  return { ...s, svg_content: await Promise.all(svgKeys.map(loadSvg)) };
}

export const staticData = {
  async motifsCount(): Promise<number> {
    return (await loadJson('motifs.json')).length;
  },

  async motif(id: string): Promise<Json> {
    const m = (await loadJson('motifs.json')).find(x => x._id === id);
    if (!m) throw new Error('Error: 404 - NOT FOUND');
    return withMotifSvg(m);
  },

  async motifs(page: number, limit: number, families: string[], query: string, sortField: string, sortOrder: string) {
    let items = await loadJson('motifs.json');
    const fams = famSet(families);
    if (fams.size) {
      items = items.filter(m => Object.keys(m.family2count).some(k => fams.has(k.toLowerCase())));
    }
    const q = query.trim();
    if (q) {
      items = items.filter(m => m._id.includes(q) || m['dot-bracket'].some((d: string) => d.includes(q)));
    }
    items = sortItems(items, MOTIF_SORT, sortField, sortOrder);
    const pageItems = await Promise.all(paginate(items, page, limit).map(withMotifSvg));
    return { totalItems: items.length, motifs: pageItems };
  },

  async struc(id: string, motifNums: string[]): Promise<Json> {
    const s = (await loadJson('strucs.json')).find(x => x._id === id);
    if (!s) throw new Error('Error: 404 - NOT FOUND');
    return withStrucSvgs(s, motifNums);
  },

  async strucs(page: number, limit: number, families: string[], query: string, sortField: string, sortOrder: string) {
    let items = await loadJson('strucs.json');
    const fams = famSet(families);
    if (fams.size) items = items.filter(s => fams.has(String(s.family).toLowerCase()));
    const q = query.trim().toLowerCase();
    if (q) items = items.filter(s => s._id.toLowerCase().includes(q) || String(s.name).toLowerCase().includes(q));
    items = sortItems(items, STRUC_SORT, sortField, sortOrder);
    const pageItems = await Promise.all(paginate(items, page, limit).map(s => withStrucSvgs(s, [])));
    return { totalItems: items.length, strucs: pageItems };
  },
};
